<template><div class="app-container"><h1>配送工作台</h1><p>餐品备好后进入待接单列表。接单后可查看完整收货信息；每15秒刷新。</p><el-alert v-if="!rider" title="请使用平台创建并启用的骑手账号登录此工作台。平台可在订单工作台查看全部订单。" :closable="false"/><template v-else><el-radio-group v-model="mode" @change="change"><el-radio-button value="AVAILABLE">待接配送</el-radio-button><el-radio-button value="MINE">我的配送</el-radio-button><el-radio-button value="DONE">历史配送</el-radio-button></el-radio-group><el-button @click="load" style="margin-left:16px">刷新</el-button><el-table :data="rows" v-loading="loading" style="margin-top:24px"><el-table-column prop="id" label="订单编号" min-width="210"/><el-table-column prop="store_name" label="取餐商家"/><el-table-column prop="zone" label="商家区域"/><el-table-column prop="store_phone" label="商家电话"/><el-table-column prop="address" label="收货信息" min-width="240"/><el-table-column label="状态"><template #default="{row}">{{row.refund_status==='REQUESTED'?'售后处理中':statuses[row.status]}}</template></el-table-column><el-table-column prop="delivery_issue" label="配送异常" min-width="180"/><el-table-column label="操作" min-width="190"><template #default="{row}"><el-button v-if="mode!=='DONE'" type="primary" :disabled="busy||row.refund_status==='REQUESTED'||!!row.delivery_issue" @click="act(row)">{{mode==='AVAILABLE'?'接配送单':'确认送达'}}</el-button><el-button v-if="mode==='MINE'&&!row.delivery_issue" :disabled="busy" @click="report(row)">上报异常</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></template></div></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import request from '@/utils/request';import useUserStore from '@/store/modules/user';import {statuses} from '@/api/food';import {ElMessageBox,ElMessage} from 'element-plus';
const rider=computed(()=>useUserStore().roles.includes('food_rider')),mode=ref('AVAILABLE'),page=ref(1),rows=ref([]),total=ref(0),loading=ref(false),busy=ref(false);let timer,revision=0;
async function load(){if(!rider.value)return;const ticket=++revision;loading.value=true;try{const r=await request({url:'/food/delivery/orders',params:{mode:mode.value,page:page.value}});if(ticket===revision){rows.value=r.data.rows;total.value=r.data.total}}finally{if(ticket===revision)loading.value=false}}
function change(){page.value=1;load()}async function act(row){try{await ElMessageBox.confirm(mode.value==='AVAILABLE'?'确认接下这笔配送订单？':'确认已将餐品交给顾客？','配送确认')}catch{return}busy.value=true;try{await request({url:'/food/delivery/orders/'+row.id+'/'+(mode.value==='AVAILABLE'?'claim':'complete'),method:'post'});ElMessage.success('配送状态已更新');await load()}finally{busy.value=false}}
async function report(row){let value;try{({value}=await ElMessageBox.prompt('例如联系不上顾客、车辆故障。上报后等待平台处理。','配送异常',{inputType:'textarea',inputValidator:v=>v?.trim().length>=2&&v.trim().length<=400||'请输入2至400字'}))}catch{return}busy.value=true;try{await request({url:'/food/delivery/orders/'+row.id+'/issue',method:'post',data:{reason:value.trim()}});ElMessage.success('异常已上报');await load()}finally{busy.value=false}}
onMounted(()=>{load();timer=setInterval(()=>{if(!loading.value&&!busy.value)load()},15000)});onBeforeUnmount(()=>{revision++;clearInterval(timer)});
</script>
